var e={name:"Shivendra Pratap Singh",role:"Founder & Patron",credentials:"",photo:"assets/brand/founder.jpg",message:["A debate is not a quarrel. It is the most demanding thing two people can do together \u2014 hold a disagreement steady for long enough to find out which side the evidence is actually on.","This forum exists so that anyone can do that properly. Take a position. Say why it follows. Show your source. Then read the other side as carefully as you would want yours read. The community decides, and it decides on reasoning \u2014 not on volume, and not on who spoke first."],signOff:"Welcome to Tarksanhita."};export{e as a};
